import{_ as t}from"./plugin-vue_export-helper-c27b6911.js";import{o as e,c as a,e as s}from"./app-7115fe16.js";const d={},n=s(`<h1 id="控件赋值问题" tabindex="-1"><a class="header-anchor" href="#控件赋值问题" aria-hidden="true">#</a> 控件赋值问题</h1><blockquote><p>为什么金蝶中给控件设置值是使用this.View.Model.SetValue()，而不是this.View.GetControl(&quot;&quot;).SetValue()呢？为什么this.view中有model、context，但是this中也有model、context呢？分别有什么区别？</p></blockquote><p>这是金蝶云·星空（BOS）插件开发中最容易混淆但又最核心的概念之一，搞清楚下面这几个对象的关系，你以后写代码就不会再迷糊了。</p><h3 id="_1-为什么给控件赋值用-this-view-model-setvalue-而不是-getcontrol-setvalue" tabindex="-1"><a class="header-anchor" href="#_1-为什么给控件赋值用-this-view-model-setvalue-而不是-getcontrol-setvalue" aria-hidden="true">#</a> 1. 为什么给控件赋值用 <code>this.View.Model.SetValue()</code> 而不是 <code>GetControl(&quot;&quot;).SetValue()</code>？</h3><table><thead><tr><th>操作方式</th><th>实际修改的是什么</th><th>适用场景</th><th>是否推荐</th></tr></thead><tbody><tr><td><code>this.View.Model.SetValue(&quot;FNumber&quot;, &quot;1001&quot;, 0)</code></td><td>修改业务数据对象（DataObject）</td><td>所有需要保存到数据库的字段赋值</td><td>强烈推荐</td></tr><tr><td><code>this.View.GetControl(&quot;FNumber&quot;).SetValue(&quot;1001&quot;)</code></td><td>只改界面显示（前端控件的值），不改后台数据</td><td>极少数只影响界面、不需要保存的临时显示</td><td>基本不用</td></tr></tbody></table><p><strong>核心原因</strong>： 金蝶是典型的“数据驱动界面”架构：</p><ul><li>所有单据真正保存的是 <code>Model.DataObject</code>（一个 DynamicObject）</li><li>界面上所有控件的值默认都是从 <code>Model.DataObject</code> 读取并绑定的</li><li>当你调用 <code>Model.SetValue()</code> 时： <ul><li>后台数据变了</li><li>框架会自动把新值推送到界面控件（双向绑定）</li><li>保存时直接保存 <code>DataObject</code></li></ul></li><li>当你用 <code>GetControl().SetValue()</code> 时： <ul><li>只改了界面控件的值</li><li><code>DataObject</code> 没变 → 保存时还是旧值</li><li>下次刷新界面又会把旧值刷回来（你改的东西就没了）</li></ul></li></ul><p><strong>官方结论</strong>（金蝶开发文档原话）：</p><blockquote><p>“在插件中，建议所有涉及业务数据的赋值操作，统一使用 Model.SetValue / Model.GetValue 接口，不要直接操作控件值。”</p></blockquote><p>只有极少数场景（比如一个只用于查询条件的文本框，不参与保存）才允许直接操作控件。</p><h3 id="_2-this-view、this-model、this-context-到底是什么-谁是谁" tabindex="-1"><a class="header-anchor" href="#_2-this-view、this-model、this-context-到底是什么-谁是谁" aria-hidden="true">#</a> 2. this.View、this.Model、this.Context 到底是什么？谁是谁？</h3><p>金蝶插件的继承链（最常见的情况）：</p><div class="language-csharp line-numbers-mode" data-ext="cs"><pre class="language-csharp"><code><span class="token keyword">public</span> <span class="token keyword">class</span> <span class="token class-name">MyBillPlugIn</span> <span class="token punctuation">:</span> <span class="token type-list"><span class="token class-name">AbstractBillPlugIn</span></span>    <span class="token comment">// ← 你的插件类</span>
<span class="token punctuation">{</span>
    <span class="token comment">// this          → 指的是你的插件实例本身（MyBillPlugIn）</span>
    <span class="token comment">// this.View     → 当前单据界面视图对象（DynamicFormView）</span>
    <span class="token comment">// this.Model    → this.View.Model 的快捷方式！！！</span>
    <span class="token comment">// this.Context  → this.View.Context 的快捷方式！！！</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><table><thead><tr><th>属性</th><th>实际对象类型</th><th>属于谁？</th><th>说明</th></tr></thead><tbody><tr><td><code>this</code></td><td>你的插件类实例（继承自 AbstractBillPlugIn 等）</td><td>插件本身</td><td>生命周期与当前单据窗口一致</td></tr><tr><td><code>this.View</code></td><td>DynamicFormView</td><td>界面层</td><td>代表整个窗体，提供了 UpdateView、ShowMessage、GetControl 等界面操作</td></tr><tr><td><code>this.Model</code></td><td>BillDataModel（实际是 this.View.Model）</td><td>数据模型层</td><td>快捷属性！等于 <code>this.View.Model</code>，操作单据业务数据</td></tr><tr><td><code>this.Context</code></td><td>BOSContext（实际是 this.View.Context）</td><td>上下文环境</td><td>快捷属性！等于 <code>this.View.Context</code>，包含用户、组织、数据库连接等信息</td></tr><tr><td><code>this.View.Model</code></td><td>BillDataModel</td><td>数据模型层</td><td>原始写法，和 this.Model 完全一样</td></tr><tr><td><code>this.View.Context</code></td><td>BOSContext</td><td>上下文环境</td><td>原始写法，和 this.Context 完全一样</td></tr></tbody></table><p><strong>金蝶在基类 AbstractBillPlugIn 中写了下面两个属性（源码）：</strong></p><div class="language-csharp line-numbers-mode" data-ext="cs"><pre class="language-csharp"><code><span class="token keyword">protected</span> <span class="token return-type class-name">IDynamicFormView</span> View <span class="token punctuation">{</span> <span class="token keyword">get</span><span class="token punctuation">;</span> <span class="token keyword">set</span><span class="token punctuation">;</span> <span class="token punctuation">}</span>
<span class="token keyword">protected</span> <span class="token keyword">new</span> <span class="token return-type class-name">FormDataModel</span> Model <span class="token operator">=&gt;</span> <span class="token keyword">this</span><span class="token punctuation">.</span>View<span class="token punctuation">.</span>Model<span class="token punctuation">;</span>      <span class="token comment">// 快捷</span>
<span class="token keyword">protected</span> <span class="token keyword">new</span> <span class="token return-type class-name">Context</span> Context <span class="token operator">=&gt;</span> <span class="token keyword">this</span><span class="token punctuation">.</span>View<span class="token punctuation">.</span>Context<span class="token punctuation">;</span>        <span class="token comment">// 快捷</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>所以：</p><ul><li><code>this.Model</code> ≡ <code>this.View.Model</code></li><li><code>this.Context</code> ≡ <code>this.View.Context</code></li></ul><p>写 <code>this.Model.SetValue()</code> 和写 <code>this.View.Model.SetValue()</code> 是 100% 等价的，只是前者更简洁。</p><h3 id="_3-总结一览表-背下来就无敌了" tabindex="-1"><a class="header-anchor" href="#_3-总结一览表-背下来就无敌了" aria-hidden="true">#</a> 3. 总结一览表（背下来就无敌了）</h3><table><thead><tr><th>写法</th><th>意思</th><th>推荐程度</th></tr></thead><tbody><tr><td><code>this.Model.SetValue(...)</code></td><td>推荐！最常用，改业务数据</td><td>★★★★★</td></tr><tr><td><code>this.View.Model.SetValue(...)</code></td><td>和上面完全一样，只是更长</td><td>★★★★</td></tr><tr><td><code>this.View.GetControl(&quot;F&quot;).SetValue(...)</code></td><td>只改界面，不改数据，几乎别用</td><td>★</td></tr><tr><td><code>this.Context.UserId</code></td><td>推荐！获取当前用户等上下文信息</td><td>★★★★★</td></tr><tr><td><code>this.View.Context.UserId</code></td><td>完全一样，只是更长</td><td>★★★★</td></tr></tbody></table><p><strong>记住金蝶开发铁律</strong>：</p><ul><li>所有业务字段的取值赋值 → 用 <code>this.Model.GetValue / SetValue</code></li><li>所有界面外观、控件显示隐藏 → 用 <code>this.View.GetControl(...)</code></li><li>所有用户、组织、数据库连接 → 用 <code>this.Context</code></li></ul><h2 id="我使用this-view-model-setvalue-给某一个修改业务字段时-setvalue的参数是控件id还是控件的绑定源属性呢" tabindex="-1"><a class="header-anchor" href="#我使用this-view-model-setvalue-给某一个修改业务字段时-setvalue的参数是控件id还是控件的绑定源属性呢" aria-hidden="true">#</a> 我使用this.View.Model.SetValue(...)给某一个修改业务字段时，SetValue的参数是控件Id还是控件的绑定源属性呢？</h2><p><strong>答案：必须传的是「绑定源属性（Field Key）」，而不是控件ID（Control Key）！</strong></p><p>这也是金蝶开发者最容易掉坑的地方之一。</p><h3 id="正确示范与错误示范对比" tabindex="-1"><a class="header-anchor" href="#正确示范与错误示范对比" aria-hidden="true">#</a> 正确示范与错误示范对比</h3><table><thead><tr><th>写法</th><th>传的是什么？</th><th>是否正确</th><th>说明</th></tr></thead><tbody><tr><td><code>this.Model.SetValue(&quot;FMaterialId&quot;, 1001)</code></td><td>绑定源属性（Field Key）</td><td>正确</td><td>推荐写法</td></tr><tr><td><code>this.Model.SetValue(&quot;F_MaterialId&quot;, 1001)</code></td><td>绑定源属性（Field Key）</td><td>正确</td><td>推荐写法（带下划线前缀的也是Field Key）</td></tr><tr><td><code>this.Model.SetValue(&quot;FEntity_FMaterialId&quot;, 1001, 0)</code></td><td>单据体绑定源属性</td><td>正确</td><td>单据体字段必须这样写</td></tr><tr><td><code>this.Model.SetValue(&quot;FTextBox1&quot;, &quot;测试&quot;)</code></td><td>控件ID（Control Key）</td><td>错误</td><td>完全无效！保存后还是空</td></tr><tr><td><code>this.Model.SetValue(&quot;FNumber&quot;, &quot;1001&quot;)</code></td><td>控件ID碰巧和Field Key一样</td><td>侥幸成功</td><td>极度不推荐，换个单据就坏了</td></tr></tbody></table><h3 id="怎么快速知道「绑定源属性-field-key-」是什么" tabindex="-1"><a class="header-anchor" href="#怎么快速知道「绑定源属性-field-key-」是什么" aria-hidden="true">#</a> 怎么快速知道「绑定源属性（Field Key）」是什么？</h3><p>有 5 种万能方法（任选其一，推荐前两种）：</p><table><thead><tr><th>方法</th><th>操作步骤</th><th>得到的结果</th></tr></thead><tbody><tr><td>方法1（最快）</td><td>在设计器里点开字段 → 看「键名」</td><td>就是你要传的字符串</td></tr><tr><td>方法2（代码里）</td><td><code>this.View.BusinessInfo.GetField(&quot;物料&quot;).Key</code></td><td>直接在代码里输出就是Field Key</td></tr><tr><td>方法3</td><td>打开单据 → F12浏览器调试 → 找 <code>&lt;input data-fieldkey=&quot;????&quot;&gt;</code></td><td>属性值就是Field Key</td></tr><tr><td>方法4</td><td>代码里遍历所有字段：<br><code>foreach (var f in this.View.BusinessInfo.GetAllFields()) { Log(f.Key); }</code></td><td>打印出来一堆，就是全部Field Key</td></tr><tr><td>方法5</td><td>单据体字段一般是：<code>实体Key + &quot;_&quot; + 字段Key</code>（如 <code>FEntity_FMaterialId</code>）</td><td>规则固定</td></tr></tbody></table><h3 id="官方铁律-金蝶文档原话" tabindex="-1"><a class="header-anchor" href="#官方铁律-金蝶文档原话" aria-hidden="true">#</a> 官方铁律（金蝶文档原话）</h3><blockquote><p><code>Model.SetValue(string fieldKey, object value, int rowIndex = -1)</code></p><ul><li>fieldKey：字段的键名（即设计器中字段属性的“键名”），不是控件键名！</li><li>单据头字段：直接写字段键名</li><li>单据体字段：写“实体键名_字段键名” 或 “实体键名.字段键名”</li></ul></blockquote><h3 id="经典错误案例-血的教训" tabindex="-1"><a class="header-anchor" href="#经典错误案例-血的教训" aria-hidden="true">#</a> 经典错误案例（血的教训）</h3><div class="language-csharp line-numbers-mode" data-ext="cs"><pre class="language-csharp"><code><span class="token comment">// 错误！FText_Material 是控件ID，不是字段键名</span>
<span class="token keyword">this</span><span class="token punctuation">.</span>Model<span class="token punctuation">.</span><span class="token function">SetValue</span><span class="token punctuation">(</span><span class="token string">&quot;FText_Material&quot;</span><span class="token punctuation">,</span> materialObj<span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// 正确！字段键名一般是 FMaterialId 或 F_MaterialId</span>
<span class="token keyword">this</span><span class="token punctuation">.</span>Model<span class="token punctuation">.</span><span class="token function">SetValue</span><span class="token punctuation">(</span><span class="token string">&quot;FMaterialId&quot;</span><span class="token punctuation">,</span> materialObj<span class="token punctuation">)</span><span class="token punctuation">;</span>           <span class="token comment">// 单据头</span>
<span class="token keyword">this</span><span class="token punctuation">.</span>Model<span class="token punctuation">.</span><span class="token function">SetValue</span><span class="token punctuation">(</span><span class="token string">&quot;FEntity_FMaterialId&quot;</span><span class="token punctuation">,</span> materialObj<span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 单据体第1行</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="终极记忆口诀-背下来一劳永逸" tabindex="-1"><a class="header-anchor" href="#终极记忆口诀-背下来一劳永逸" aria-hidden="true">#</a> 终极记忆口诀（背下来一劳永逸）</h3><blockquote><p>“Model 改数据，传 FieldKey；<br> 控件改显示，才用 ControlKey。<br> 99% 的业务字段赋值，都只用 Model.SetValue(FieldKey, ...)”</p></blockquote><p>记住了这点，你在金蝶里给字段赋值就永远不会再出错了。</p>`,38),o=[n];function l(i,c){return e(),a("div",null,o)}const u=t(d,[["render",l],["__file","金蝶给控件赋值.html.vue"]]);export{u as default};
